std::vector<Halfedge_handle> border_cycles;
for (Halfedge_iterator hit = poly.halfedges_begin(); hit != poly.halfedges_end(); ++hit) {
    if (hit->is_border() && hit->next()->is_border() && hit->next()->next()->is_border()) {
        bool found = false;
        for (const auto& cycle : border_cycles) {
            if (cycle == hit || cycle == hit->opposite()) {
                found = true;
                break;
            }
        }
        if (!found) {
            border_cycles.push_back(hit);
        }
    }
}

for (Halfedge_handle border : border_cycles) {
    std::vector<Vertex_handle> cycle_vertices;
    Halfedge_handle curr = border;
    do {
        cycle_vertices.push_back(curr->vertex());
        curr = curr->next();
    } while (curr != border);

    if (cycle_vertices.size() < 3) continue;

    std::vector<std::size_t> indices(cycle_vertices.size());
    for (std::size_t i = 0; i < cycle_vertices.size(); ++i) {
        indices[i] = i;
    }

    std::vector<std::array<std::size_t, 3>> triangles;
    std::vector<bool> reflex(cycle_vertices.size(), false);
    for (std::size_t i = 0; i < cycle_vertices.size(); ++i) {
        std::size_t prev = (i + cycle_vertices.size() - 1) % cycle_vertices.size();
        std::size_t next = (i + 1) % cycle_vertices.size();
        Point_3 a = cycle_vertices[prev]->point();
        Point_3 b = cycle_vertices[i]->point();
        Point_3 c = cycle_vertices[next]->point();
        Vector_3 ab = b - a;
        Vector_3 ac = c - a;
        Vector_3 cross = CGAL::cross_product(ab, ac);
        if (cross * Vector_3(0, 0, 1) < 0) {
            reflex[i] = true;
        }
    }

    std::size_t n = cycle_vertices.size();
    while (n > 3) {
        bool ear_found = false;
        for (std::size_t i = 0; i < n; ++i) {
            if (reflex[i]) continue;
            std::size_t prev = (i + n - 1) % n;
            std::size_t next = (i + 1) % n;
            Point_3 a = cycle_vertices[indices[prev]]->point();
            Point_3 b = cycle_vertices[indices[i]]->point();
            Point_3 c = cycle_vertices[indices[next]]->point();
            bool valid = true;
            for (std::size_t j = 0; j < n; ++j) {
                if (j == prev || j == i || j == next) continue;
                Point_3 p = cycle_vertices[indices[j]]->point();
                if (CGAL::orientation(a, b, c) == CGAL::POSITIVE &&
                    CGAL::orientation(a, b, p) == CGAL::POSITIVE &&
                    CGAL::orientation(b, c, p) == CGAL::POSITIVE &&
                    CGAL::orientation(c, a, p) == CGAL::POSITIVE) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                triangles.push_back({{indices[prev], indices[i], indices[next]}});
                indices.erase(indices.begin() + i);
                reflex.erase(reflex.begin() + i);
                n--;
                ear_found = true;
                break;
            }
        }
        if (!ear_found) break;
    }
    if (n == 3) {
        triangles.push_back({{indices[0], indices[1], indices[2]}});
    }

    for (const auto& tri : triangles) {
        poly.add_facet(
            cycle_vertices[tri[0]],
            cycle_vertices[tri[1]],
            cycle_vertices[tri[2]]
        );
    }
}
